export type SchedulePathDto = {
  readonly kind: "instant" | "standard";
  readonly cadence: "continuous" | "daily_cutoff" | "periodic" | "scheduled";
  readonly status: "open" | "closed" | "settling";
  readonly businessDaysOnly?: boolean;
  readonly cutoffTime?: string;
  readonly currentWindow?: {
    readonly opensAt: string;
    readonly closesAt: string;
    readonly source?: "onchain" | "api" | "config";
  } | null;
  readonly nextWindow?: {
    readonly opensAt: string;
    readonly closesAt: string;
    readonly source?: "onchain" | "api" | "config";
  } | null;
  readonly settlement: {
    readonly type: "atomic" | "next_business_day" | "cohort" | "cooldown";
    readonly marketDays?: number;
    readonly estimatedDuration?: { readonly seconds: number };
    readonly estimatedSettlementAt?: string;
    readonly claimRequired?: boolean;
    readonly instantPortion?: number;
    readonly deferredDeliveryAt?: string;
  };
  readonly accrual: {
    readonly startsAt:
      | "immediate"
      | "next_business_day"
      | "on_cycle_start"
      | "on_settlement";
    readonly startsAtDate?: string;
    readonly minimumHold?: { readonly seconds: number };
  };
  readonly limits?: {
    readonly individualPer24h?: string;
    readonly globalPer24h?: string;
    readonly globalRemainingPer24h?: string;
    readonly maxFractionOfNav?: number;
    readonly liquidityBounded?: boolean;
    readonly availableLiquidity?: string;
    readonly minimumAmount?: string;
  };
  readonly fee?: { readonly rate: number };
};
export const SchedulePathDto = Schema.Struct({
  kind: Schema.Literals(["instant", "standard"]).annotate({
    description:
      "instant = atomic same-tx, liquidity/limit-bounded; standard = windowed / off-chain settled",
  }),
  cadence: Schema.Literals([
    "continuous",
    "daily_cutoff",
    "periodic",
    "scheduled",
  ]).annotate({ description: "How the path recurs" }),
  status: Schema.Literals(["open", "closed", "settling"]).annotate({
    description: "Live status, refreshed by cron / on-chain read",
  }),
  businessDaysOnly: Schema.optionalKey(
    Schema.Boolean.annotate({
      description:
        "false/omitted = 24/7/365 (instant DeFi paths); true = market days only",
    })
  ),
  cutoffTime: Schema.optionalKey(
    Schema.String.annotate({
      description:
        'For daily_cutoff: local cutoff time orders must be in by, e.g. "16:00"',
      examples: ["16:00"],
    })
  ),
  currentWindow: Schema.optionalKey(
    Schema.Union([
      Schema.Struct({
        opensAt: Schema.String.annotate({
          description: "Window open time (ISO 8601)",
          examples: ["2026-07-21T08:00:00Z"],
        }),
        closesAt: Schema.String.annotate({
          description:
            "Window close / cutoff time (ISO 8601); orders after this roll to nextWindow",
          examples: ["2026-07-27T20:00:00Z"],
        }),
        source: Schema.optionalKey(
          Schema.Literals(["onchain", "api", "config"]).annotate({
            description:
              "Provenance of this window (on-chain read, issuer API, or hardcoded config)",
          })
        ),
      }).annotate({
        description:
          "The window the user is acting into right now (null when continuous)",
      }),
      Schema.Null,
    ])
  ),
  nextWindow: Schema.optionalKey(
    Schema.Union([
      Schema.Struct({
        opensAt: Schema.String.annotate({
          description: "Window open time (ISO 8601)",
          examples: ["2026-07-21T08:00:00Z"],
        }),
        closesAt: Schema.String.annotate({
          description:
            "Window close / cutoff time (ISO 8601); orders after this roll to nextWindow",
          examples: ["2026-07-27T20:00:00Z"],
        }),
        source: Schema.optionalKey(
          Schema.Literals(["onchain", "api", "config"]).annotate({
            description:
              "Provenance of this window (on-chain read, issuer API, or hardcoded config)",
          })
        ),
      }).annotate({
        description:
          "The next window after the current one closes; what a UI counts down to",
      }),
      Schema.Null,
    ])
  ),
  settlement: Schema.Struct({
    type: Schema.Literals([
      "atomic",
      "next_business_day",
      "cohort",
      "cooldown",
    ]).annotate({
      description:
        "How the order settles: atomic (same tx), next_business_day, cohort (batched off-chain), or cooldown (fixed delay)",
    }),
    marketDays: Schema.optionalKey(
      Schema.Number.annotate({
        description: "Settlement horizon in market days (T+N) when applicable",
        examples: [1],
      }).check(Schema.isFinite())
    ),
    estimatedDuration: Schema.optionalKey(
      Schema.Struct({
        seconds: Schema.Number.annotate({
          description: "Duration in seconds",
          examples: [86400],
        }).check(Schema.isFinite()),
      }).annotate({
        description: "Best estimate of full settlement when not atomic",
      })
    ),
    estimatedSettlementAt: Schema.optionalKey(
      Schema.String.annotate({
        description:
          "Concrete settlement date when known (ISO 8601, cohort/scheduled)",
      })
    ),
    claimRequired: Schema.optionalKey(
      Schema.Boolean.annotate({
        description:
          "User must submit a separate on-chain claim to receive settled funds (ERC-7540)",
      })
    ),
    instantPortion: Schema.optionalKey(
      Schema.Number.annotate({
        description:
          "Split delivery: fraction (0-1) delivered instantly; the rest is deferred",
        examples: [0.93],
      }).check(Schema.isFinite())
    ),
    deferredDeliveryAt: Schema.optionalKey(
      Schema.String.annotate({
        description:
          "Concrete date the deferred portion is delivered (ISO 8601)",
      })
    ),
  }).annotate({ description: "When the order is actually processed" }),
  accrual: Schema.Struct({
    startsAt: Schema.Literals([
      "immediate",
      "next_business_day",
      "on_cycle_start",
      "on_settlement",
    ]).annotate({
      description:
        "When earning starts (subscription) / earn-through boundary (redemption): immediate, next_business_day, on_cycle_start, or on_settlement",
    }),
    startsAtDate: Schema.optionalKey(
      Schema.String.annotate({
        description:
          "Concrete accrual start date when known (ISO 8601, cron-filled)",
      })
    ),
    minimumHold: Schema.optionalKey(
      Schema.Struct({
        seconds: Schema.Number.annotate({
          description: "Duration in seconds",
          examples: [86400],
        }).check(Schema.isFinite()),
      }).annotate({ description: "Minimum hold before redemption is allowed" })
    ),
  }).annotate({
    description: "When earning starts/stops relative to the order",
  }),
  limits: Schema.optionalKey(
    Schema.Struct({
      individualPer24h: Schema.optionalKey(
        Schema.String.annotate({
          description: "Per-investor cap per rolling 24h",
        })
      ),
      globalPer24h: Schema.optionalKey(
        Schema.String.annotate({
          description: "Protocol-wide cap per rolling 24h",
        })
      ),
      globalRemainingPer24h: Schema.optionalKey(
        Schema.String.annotate({
          description:
            "Live remaining protocol-wide capacity in the current rolling 24h window (globalPer24h minus used); computed at request time",
        })
      ),
      maxFractionOfNav: Schema.optionalKey(
        Schema.Number.annotate({
          description: "On-demand pool cap as a fraction of NAV (0-1)",
          examples: [0.05],
        }).check(Schema.isFinite())
      ),
      liquidityBounded: Schema.optionalKey(
        Schema.Boolean.annotate({
          description:
            "Path depends on an on-chain liquidity buffer; live depth lives in state.liquidityState",
        })
      ),
      availableLiquidity: Schema.optionalKey(
        Schema.String.annotate({
          description:
            "Live liquidity available to this path right now, in the payout token; computed at request time",
          examples: ["323155"],
        })
      ),
      minimumAmount: Schema.optionalKey(
        Schema.String.annotate({
          description:
            "Per-path minimum when it differs from mechanics.entryLimits",
        })
      ),
    }).annotate({
      description:
        "Caps that gate an instant path or an on-demand liquidity pool",
    })
  ),
  fee: Schema.optionalKey(
    Schema.Struct({
      rate: Schema.Number.annotate({
        description:
          "Fee charged on this path as a decimal fraction of the amount (0.0007 = 0.07%)",
        examples: [0.0007],
      }).check(Schema.isFinite()),
    }).annotate({
      description:
        "Fee this path charges on the amount (e.g. instant redemption fee)",
    })
  ),
});
