export const BalanceHistorySnapshotDto = Schema.Struct({
  timestamp: Schema.String.annotate({
    description: "Timestamp of this snapshot (ISO 8601)",
    examples: ["2025-07-12T00:00:00.000Z"],
  }),
  blockNumber: Schema.Number.annotate({
    description: "Block number closest to this snapshot",
    examples: [20540000],
  }).check(Schema.isFinite()),
  yieldId: Schema.String.annotate({
    description: "Unique identifier of the yield",
    examples: ["ethereum-eth-lido-staking"],
  }),
  balances: Schema.Array(BalanceDto).annotate({
    description: "Balance entries at this point in time",
  }),
  periodDelta: Schema.optionalKey(
    Schema.Struct({
      shareAmount: Schema.String.annotate({
        description:
          "Net vault share balance change from indexed transfers during this period",
        examples: ["1.000000000000000000"],
      }),
      shareAmountRaw: Schema.String.annotate({
        description: "Net vault share balance change in base units (wei)",
        examples: ["1000000000000000000"],
      }),
      amount: Schema.String.annotate({
        description:
          "Net change in underlying position vs the previous snapshot (includes price-per-share effects)",
        examples: ["0.050000000000000000"],
      }),
      amountRaw: Schema.String.annotate({
        description: "Net underlying position change in base units",
        examples: ["50000000000000000"],
      }),
    }).annotate({
      description:
        "Balance delta during this period vs the previous snapshot. Omitted for point-in-time (blockNumber) queries.",
    })
  ),
});
